-- Operaciones del nicho construcción: alertas de vencimiento compliance + daily reports\n\nALTER TABLE compliance_requirement\n  ADD COLUMN IF NOT EXISTS expiry_alerted_at timestamptz,\n  ADD COLUMN IF NOT EXISTS expiry_alert_level smallint NOT NULL DEFAULT 0;\n  -- 0=none, 1=30d, 2=7d, 3=expired\n\nCREATE TYPE daily_report_status AS ENUM ('DRAFT','SUBMITTED','REVIEWED','ARCHIVED');\n\nCREATE TABLE IF NOT EXISTS daily_report (\n  tenant_id       uuid NOT NULL,\n  report_id       uuid NOT NULL,\n  project_id      uuid NOT NULL,\n  site_id         uuid,\n  report_date     date NOT NULL,\n  weather         varchar(80),\n  workforce_count int,\n  summary         text NOT NULL,\n  status          daily_report_status NOT NULL DEFAULT 'DRAFT',\n  document_id     uuid,\n  submitted_by    uuid NOT NULL,\n  submitted_at    timestamptz,\n  aggregate_version bigint NOT NULL DEFAULT 1,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  updated_at      timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, report_id),\n  UNIQUE (tenant_id, project_id, report_date)\n);\n\nALTER TABLE daily_report ENABLE ROW LEVEL SECURITY;\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_policies WHERE tablename = 'daily_report' AND policyname = 'ti_daily_report'\n  ) THEN\n    CREATE POLICY ti_daily_report ON daily_report\n      USING (tenant_id = current_setting('app.tenant_id')::uuid);\n  END IF;\nEND $$;\n\nCREATE INDEX IF NOT EXISTS idx_compliance_expiring\n  ON compliance_requirement (tenant_id, fecha_vencimiento)\n  WHERE estado_verificacion = 'VERIFICADO';